// T-AC-04: authenticate the raw HTTP bytes before recording CI intent.
describe("GitHub raw-body HTTP boundary", () => {
  let store: Store;
  let core: ControlPlane;
  let app: ReturnType<typeof createApp>;
  const hookUrl = new URL("/hooks/github", apiUrl).href;

  beforeEach(async () => {
    store = await openStore();
    core = new ControlPlane(store);
    const project = await core.createProject(owner, projectInput, randomUUID());
    await core.configureRepository(owner, project.id, repository, project.revision, randomUUID());
    app = createApp(
      core,
      loadConfiguration({
        GODSEYE_MODE: "local",
        GODSEYE_GITHUB_WEBHOOK_KEY: webhookKey,
      }),
    );
  });

  afterEach(async () => {
    await store.close();
  });

  it("T41 preserves signed pretty-printed JSON bytes through the HTTP middleware", async () => {
    const delivery = signedDelivery(JSON.stringify(githubPush(), null, 2));

    const response = await app.request(hookUrl, {
      method: "POST",
      headers: {
        ...localHeaders,
        "x-github-delivery": delivery.deliveryId,
        "x-github-event": delivery.event,
        "x-hub-signature-256": delivery.signature,
      },
      body: Buffer.from(delivery.rawBody).toString("utf8"),
    });

    expect(response.status).toBe(202);
    expect(await response.json()).toMatchObject({ outcome: "queued" });
    const runs = await core.listCiRuns(owner);
    expect(runs).toHaveLength(1);
    expect(runs[0]).toMatchObject({ status: "pending_verification", commitSha: "a".repeat(40) });
  });

  it("T41 rejects reserialized HTTP bytes paired with the original raw-body signature", async () => {
    const delivery = signedDelivery(JSON.stringify(githubPush(), null, 2));
    const headers = {
      ...localHeaders,
      "x-github-delivery": delivery.deliveryId,
      "x-github-event": delivery.event,
      "x-hub-signature-256": delivery.signature,
    };
    const accepted = await app.request(hookUrl, {
      method: "POST",
      headers,
      body: Buffer.from(delivery.rawBody).toString("utf8"),
    });
    expect(accepted.status).toBe(202);

    const changed = await app.request(hookUrl, {
      method: "POST",
      headers,
      body: JSON.stringify(githubPush()),
    });

    expect(changed.status).toBe(401);
    expect((await changed.json()) as ApiErrorBody).toMatchObject({
      error: { code: "INVALID_SIGNATURE" },
    });
    expect(await core.listCiRuns(owner)).toHaveLength(1);
  });

  it("T41 refuses the webhook route when its verification key is not configured", async () => {
    const unconfigured = createApp(core, loadConfiguration({ GODSEYE_MODE: "local" }));
    const delivery = signedDelivery();

    const response = await unconfigured.request(hookUrl, {
      method: "POST",
      headers: {
        ...localHeaders,
        "x-github-delivery": delivery.deliveryId,
        "x-github-event": delivery.event,
        "x-hub-signature-256": delivery.signature,
      },
      body: Buffer.from(delivery.rawBody).toString("utf8"),
    });

    expect(response.status).toBe(503);
    expect((await response.json()) as ApiErrorBody).toMatchObject({
      error: { code: "CAPABILITY_UNAVAILABLE" },
    });
    expect(await core.listCiRuns(owner)).toHaveLength(0);
  });
});

